import { styled } from '@hexa-ui/theme';

export const StyledContainer = styled('div', {
  display: 'flex',
  width: '100%',
  '& > *': {
    flex: '1 1 0',
    minWidth: '0 !important',
    maxWidth: 'none !important',
  },
  variants: {
    gap: {
      8: { gap: '8px' },
      16: { gap: '16px' },
    },
  },
});
